from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from pipeline import RUN,ROOT,read,dump

def pct(x):return f'{100*x:.1f}%'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(map(str,r))+' |' for r in rows])
def main():
    r=read(RUN/'test_results.json');s=read(RUN/'selection_frozen.json');a=read(RUN/'integrity_audit.json');pilot=read(RUN/'pilot_audit.json');opp=read(RUN/'repair_opportunity.json');strict=read(RUN/'strict_format_sensitivity.json');cfg=read(RUN/'config.json');shuffle=read(RUN/'label_shuffle_validation.json');sel=s['selection'];ci=r['paired_bootstrap']
    lines=['# GSM8K Experiments A and B — completed exploratory run','', 'Completed on '+datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=9))).strftime('%Y-%m-%d %H:%M KST')+'. Experiment C was not run.','',
    '## Main findings','',f"A: D3 external AUROC was **{r['A']['D3']['AUROC']:.3f}**; D4 with hidden states was **{r['A']['D4']['AUROC']:.3f}**. The paired difference was **{ci['A_D4_minus_D3_AUROC']['difference']:+.3f}**, 95% bootstrap CI [{ci['A_D4_minus_D3_AUROC']['ci95'][0]:+.3f}, {ci['A_D4_minus_D3_AUROC']['ci95'][1]:+.3f}]. This is an exploratory, conditional-on-training comparison, not a general claim about hidden states.",'',
    f"B: external selection reached **{pct(r['B']['external']['final_accuracy'])}**, internal selection **{pct(r['B']['internal']['final_accuracy'])}**, and the validation-selected fixed policy ({sel['best_fixed']}) **{pct(r['B']['best_fixed']['final_accuracy'])}**. Internal minus external was **{100*ci['B_internal_minus_external']['difference']:+.1f} percentage points**, CI [{100*ci['B_internal_minus_external']['ci95'][0]:+.1f}, {100*ci['B_internal_minus_external']['ci95'][1]:+.1f}]. B was run independently of A's findings.",'',
    ('Neither primary hidden-state gain is established by this run: both paired intervals include zero. B’s internal selector also has lower point accuracy and more harmful revisions than its external counterpart.' if all(v['ci95'][0]<=0<=v['ci95'][1] for v in [ci['A_D4_minus_D3_AUROC'],ci['B_internal_minus_external']]) else 'Interpret each paired interval separately; a directional point estimate alone is not evidence of a reliable gain.'),'',
    '## Cohorts and provenance','',table(['Split','N','Correct originals','Errors','Calculator available','Truncated originals'],[[k,v['n'],v['n']-v['errors'],v['errors'],v['recalculate_available'],v['original_truncated']] for k,v in a['split_summary'].items()]),'',
    'Pilot, train, and validation come from official GSM8K train. Final evaluation uses a fixed 100-example subset of official GSM8K test, never the old train-derived test. The pilot is excluded from all fitting and evaluation. Exact normalized question duplicates stay together; no reliable paraphrase/family IDs are available. All methods use the same records and pre-repair features. No examples were resampled based on correctness.','',
    f"Model: `{cfg['model']}` at `{cfg['model_revision']}`. Dataset: `{cfg['dataset']}` (`main`) at `{cfg['data_revision']}`. Seed: {cfg['seed']}. Original/repair generation: greedy with inherited repetition penalty 1.1, 512 new tokens maximum. Verification: up to 8 tokens, exact CORRECT/INCORRECT parsing. Frozen LLM; only small logistic classifiers and training-only preprocessing are fit.",'',
    'The local prior run supplies 320 original responses (40 pilot + 200 train + 80 validation), their original token IDs and generation NLL. All old results remain unchanged. The 100 official-test originals are newly generated once. New verification features and independent repairs are collected for all 420 examples. The current GPU is GTX 1080 Ti 11 GB. New inference is FP32; cached original responses were FP16 on V100. The precision difference and reused training responses limit train/test comparability.','',
    "The team's meeting PDF also uses Qwen2.5-1.5B-Instruct and greedy decoding, but a different #### prompt, 1,024-token originals, 800/200 train/validation and the full 1,319-example test set. This run aligns the model family and decoding, while retaining the older local 512-token prompt to reuse originals. It is not a controlled replication of the team's numerical results.",'',
    '## Pilot and implementation checks','',f"Final pilot: {pilot['correct']} correct and {pilot['errors']} incorrect originals; {pilot['different_actions_help']} errors were repairable by at least one action; oracle {pilot['oracle_successes']}/40. Calculator availability {pilot['recalculate_available']}/40. All 40 verifier outputs parsed. All 36 prefix-vs-full hidden comparisons passed (maximum relative L2 {max(pilot['causal_checks']):.2g}). Peak allocated memory {pilot['peak_gpu_allocated_bytes']/1e9:.2f} GB; reserved {pilot['peak_gpu_reserved_bytes']/1e9:.2f} GB. Corrected pilot collection cost {pilot['collection_seconds']:.1f} seconds, excluding initial debug work and historical original generation.",'',
    'Pilot debugging found and fixed (1) BPE merging the newline boundary with final response punctuation; (2) credit for unfinished repairs under a 256-token cap, leading to a 512-token cap and rejection of truncated fallback answers; (3) last-number extraction choosing an incidental quantity after the answer. The concluding-clause correction was based on pilot example gsm8k_train_3784 and changed only that pilot label; already collected main records were rescored before fitting. Debug outputs, previous labels, and protocol amendments are retained.','',
    'Scoring prefers explicit final markers, numeric boxed answers, then a numeric complement of a concluding verb on the final nonempty line, then a last-number fallback. Truncated responses need an explicit final marker or boxed answer. Exact Decimal equality normalizes dollar signs, commas, and decimals; percentages remain in question units, with no gold-based rounding. This is final numeric answer scoring, not a judgment that every reasoning step is correct.','',
    '## A: incorrect-original detection','',table(['Detector','AUROC','Error AP','Brier','Top-20% error recall','FPR at 0.5'],[[name,f"{v['AUROC']:.3f}",f"{v['AP']:.3f}",f"{v['Brier']:.3f}",pct(v['error_recall_top20']),pct(v['false_alarm_rate_at_half'])] for name,v in r['A'].items()]),'',f"Test error prevalence is {pct(r['original_errors']/r['n'])}; this is the no-skill AP reference. AP is average precision, not trapezoidal PR-AUC. The 0.5 threshold and top-20% review fraction are fixed in advance.",'',
    'D1: original mean raw-model token NLL + log token length. NLL is teacher-forced at the preceding logit position and excludes special tokens; it is not the repetition-penalized decoding-score probability. D2: D1 + train-fit question/response TF-IDF (up to 1,500 unigram/bigram terms). D3: D2 + explicit verifier judgment indicators and mean generated-verdict token NLL. D4: D3 + one selected 1,536-dimensional hidden vector. The lexical text baseline is modest; this does not compare against every external semantic detector.','',
    table(['Model','Selected hidden vector','C','Validation AUROC'],[[k,sel[k]['key'] or 'none',sel[k]['C'],f"{sel[k]['validation_auroc']:.3f}"] for k in ['D1','D2','D3','D4']]),'',
    'Hidden candidates: last completed-response token (possibly punctuation), dedicated two-newline boundary token, final verification-prompt token before generating any verdict; raw outputs of blocks 7/14/21/28, before final model normalization. Exact token IDs/offsets are saved per record. Segmented verification encoding guarantees a distinct separator token and is reused unchanged for verdict generation. All 12 vectors are retained for later work. Only one vector is added per candidate detector, with training-only coordinate scaling and division by sqrt(1536).','',
    f"Validation-only label shuffle sanity check (20 fits at frozen selected settings): D3 mean AUROC {shuffle['D3']['mean']:.3f}, range {shuffle['D3']['min']:.3f}–{shuffle['D3']['max']:.3f}; D4 mean {shuffle['D4']['mean']:.3f}, range {shuffle['D4']['min']:.3f}–{shuffle['D4']['max']:.3f}. These are sanity checks, not test-set tuning.",'',
    '## B: selecting independent actions','',table(['Policy','Accuracy','Errors repaired','Repair rate among errors','Correct answers harmed','Harm rate among correct'],[[k,pct(v['final_accuracy']),v['successful_repairs'],pct(v['incorrect_to_correct_rate']),v['harmful_revisions'],pct(v['correct_to_incorrect_rate'])] for k,v in r['B'].items()]),'',
    f"The best fixed policy selected on validation is **{sel['best_fixed']}**; the best fixed repair excluding Keep is **{sel['best_fixed_repair']}**. Validation fixed accuracies: "+', '.join(f'{k} {pct(v)}' for k,v in sel['fixed_validation_accuracy'].items())+'. Unavailable Recalculate falls back to Keep in fixed-policy evaluation.','',
    table(['Selector','Hidden vector','C','Validation final accuracy','Test action counts'],[[k,sel[k]['key'] or 'none',sel[k]['C'],pct(sel[k]['validation_accuracy']),str(r['B'][k]['selected_actions'])] for k in ['external','internal']]),'',
    'Four independent binary heads predict [Keep, Recalculate, Rebuild, Review] success; multiple actions may succeed. Keep = 1 − A error label is checked for every example. Missing calculator outcomes are excluded from that head’s fitting and masked at decision time. A constant fallback handles single-class heads. Inputs contain question/response text, generation and verification measurements, plus hidden states for the internal version. No gold answers, reference reasoning, observed repair output, or success label enters prediction.','',
    'Recalculate uses a conservative safe Decimal calculator on an explicit numeric equality whose RHS matches the model’s own extracted final answer. Symbolic or unreliable extraction is unavailable. Rebuild sees only the original question; Review sees the question and original response. Repairs never receive another repair’s result. Selection uses only pre-repair features and availability.','',
    table(['Split','Best fixed accuracy','Oracle action accuracy','Potential gain','Repairable errors'],[[k,pct(v['best_fixed_accuracy']),pct(v['oracle_accuracy']),f"{100*v['oracle_minus_best_fixed']:.1f} pp",v['repairable_errors']] for k,v in opp.items()]),'',
    'The oracle is a diagnostic upper bound using observed outcomes, not a deployable selector. Its train/validation advantage measures whether action choice has any opportunity to help; a learned selector must find that opportunity without seeing outcomes.','',
    '## Paired uncertainty','',table(['Difference','Point estimate','95% bootstrap interval','Valid resamples'],[[k,f"{v['difference']:+.4f}",f"[{v['ci95'][0]:+.4f}, {v['ci95'][1]:+.4f}]",v['valid']] for k,v in ci.items()]),'',
    '2,000 paired question-level bootstrap resamples with seed 20261013. AUROC/AP resamples lacking both classes are excluded. Intervals condition on the trained models and chosen sample; they do not include retraining or hyperparameter-selection variability. The 100-example test set has coarse accuracy resolution and broad uncertainty.','',
    '## Compute and storage','',table(['Split','N','New original generation (s)','Verifier generation (s)','Hidden pass (s)','All repairs (s)','Collection wall (s)'],[[k,v['n'],f"{v['original_generation_seconds']:.1f}",f"{v['verification_generation_seconds']:.1f}",f"{v['hidden_extraction_seconds']:.1f}",f"{v['all_repair_generation_seconds']:.1f}",f"{v['record_collection_wall_seconds']:.1f}"] for k,v in r['costs'].items()]),'',
    f"Small-model training and validation search took {s['training_seconds']:.1f} seconds on CPU. CPU feature transformation plus prediction over 100 test examples: "+', '.join(f'{k} {v:.3f}s' for k,v in r['feature_transform_and_prediction_seconds'].items())+'.','',
    'Offline data collection evaluates both generative repairs for every example to obtain independent labels. Applying a frozen selector needs only original-response features, initial verification, any selected hidden pass, CPU prediction, and one chosen repair. Fixed policies do not require verification. Batched repair wall time is apportioned across examples and measures throughput, not one-request latency. Historical cached-original generation, dependency installation, downloads, interrupted/debug passes, and model-loading time are excluded from the main stage totals. Verifier confidence teacher forcing is included in collection wall time but not separately timed.','',
    table(['Policy','Selected repair time on test (s, batch-amortized)','Selected repair tokens'],[[k,f"{v['selected_repair_seconds']:.1f}",v['selected_repair_tokens']] for k,v in r['B'].items()]),'',
    f"Peak allocated GPU memory across all phases was {max(v['max_gpu_allocated_bytes'] for v in r['costs'].values())/1e9:.2f} GB; peak reserved memory was {max(v['max_gpu_reserved_bytes'] for v in r['costs'].values())/1e9:.2f} GB. Recorded collection time totals {sum(v['record_collection_wall_seconds'] for v in r['costs'].values())/60:.1f} minutes, including the corrected pilot.",'',
    'Persistent artifacts include small hidden arrays and text/token records; full vocabulary logits and all-layer activations are not retained. Large weights and the rebuilt environment are under `/tmp/yaicon-ab`; they can disappear when the container restarts. `storage.json` records final usage and free space.','',
    '## Sensitivity and limitations','',
    f"Under strict Final answer: <number> formatting, original accuracy is {pct(strict['original_accuracy'])}; with choices held fixed, external selector accuracy is {pct(strict['selected_policy_accuracy']['external'])} and internal is {pct(strict['selected_policy_accuracy']['internal'])}. Strict-label D3/D4 AUROC are {strict['D3_AUROC']:.3f}/{strict['D4_AUROC']:.3f}. This is a rescoring sensitivity analysis, not a second tuned experiment.",'',
    'Remaining limitations: modest train/validation size, 100-test subset, one model and one data/split seed, lexical text representation, a mean-NLL confidence baseline (not every richer confidence/entropy control), conservative calculator coverage, residual rule-based extraction errors, token-budget failures, validation selection over 12 hidden candidates, and training/test inference precision differences. Cached original responses may contain benchmark contamination inherited from model pretraining. Results concern natural generated final-answer errors, not error types or step-level causal mechanisms. Negative findings should not be generalized to larger samples or other models.','',
    '## Artifacts and reproduction','',
    '- Runnable code and detailed protocol: `../../experiments/ab/README.md`.',
    '- Resumption: `bash experiments/ab/run.sh` from repository root.',
    '- Settings and split IDs: `config.json`, `manifest.json`, `protocol_frozen.json`.',
    '- Source specification and team reference: `source_notion.txt`, `team_reference.txt`.',
    '- Pilot checks and debug history: `pilot_audit.json`, `pilot_integrity.json`, `pilot_debug_v1/`, `pilot_conclusion_fix.json`.',
    '- Raw inference and reusable features: `stages/`, `records/`, `hidden/`.',
    '- Training/validation: `trained.joblib`, `selection_frozen.json`, `validation_grid.json`, `repair_opportunity.json`.',
    '- Final results: `test_results.json`, `test_predictions.json`, `strict_format_sensitivity.json`, `integrity_audit.json`.',
    '- Human-readable examples: `examples.json`; figures: `results.png`, `paired_differences.png`.',
    '- Experiment C is deferred; no C variants, C training, or C results are claimed.','']
    if (RUN/'deployment_benchmark.json').exists():
        d=read(RUN/'deployment_benchmark.json');at=lines.index('## Sensitivity and limitations');lines[at:at]=['Batch-one deployment timing: mean seconds over six excluded pilot questions, model already loaded and original response/NLL already available. This is a latency benchmark, not an accuracy evaluation.','',table(['Selector','Verification','Extra hidden pass','CPU classifier','Selected repair','Total'],[[k]+[f"{v[col]:.3f}" for col in ['verification_seconds','extra_hidden_seconds','classifier_seconds','selected_repair_seconds','total_incremental_seconds']] for k,v in d['summary'].items()]),'']
    storage=read(RUN/'storage.json')
    lines.extend(['## Storage snapshot','',f"Persistent run artifacts occupy approximately {storage['persistent_run_bytes']/1e6:.1f} MB; workspace free space is {storage['workspace_disk']['free']/1e9:.1f} GB. Temporary environment/cache usage: {storage['temporary_environment_and_cache']}. Previous results were preserved.",''])
    quality=read(RUN/'reference_quality.json')
    lines.extend(['## Observed dataset reference inconsistency','', 'A non-exhaustive qualitative review found an erroneous official reference for `gsm8k_test_823`: Sasha scored 14 in the first game and 10−6=4 in the second, totaling 18. The reference mistakenly adds Julie’s first-game 10 instead and gives 14. The model’s 18 is counted as an error by official-reference scoring. Primary labels, models, and choices are unchanged.','',f"Excluding only this flagged example (post-hoc sensitivity, N=99), D3/D4 AUROC are {quality['A']['D3']['AUROC']:.3f}/{quality['A']['D4']['AUROC']:.3f}; external/internal policy accuracy is {pct(quality['B']['external'])}/{pct(quality['B']['internal'])}, Keep {pct(quality['B']['keep'])}, and the fixed policy {pct(quality['B']['best_fixed'])}. See reference_quality.json. This does not certify the other references as error-free.",''])
    lines.extend(['## Figures','', '![A and B point estimates](results.png)','', '![Paired differences and uncertainty](paired_differences.png)',''])
    position_summary=read(RUN/'validation_position_summary.json')
    lines.extend(['## Validation comparison by hidden position','',table(['Experiment','Position','Layer/C','Validation metric'],[[x['experiment'],x['position'],str(x['key'])+' / '+str(x['C']),f"{x.get('validation_auroc',x.get('validation_accuracy')):.3f}"] for x in position_summary]),'', 'These are validation-selected comparisons, not additional independent test results. The primary official-test comparison uses only the globally selected vector for each experiment.',''])
    (RUN/'REPORT.md').write_text('\n'.join(lines))
    ko=f'''# GSM8K A/B 실험 결과\n\n완료: pilot 40, train 200, validation 80, 공식 test 100. C는 보류했습니다. 기존 원본 응답 320개를 재사용하고 공식 test 원본 100개만 새로 생성했습니다. 이전 결과는 보존했습니다.\n\n- A: 외부 D3 AUROC {r['A']['D3']['AUROC']:.3f}, hidden 추가 D4 {r['A']['D4']['AUROC']:.3f}. 차이 {ci['A_D4_minus_D3_AUROC']['difference']:+.3f}, paired bootstrap 95% CI {ci['A_D4_minus_D3_AUROC']['ci95']}.\n- B: 외부 selector 정확도 {pct(r['B']['external']['final_accuracy'])}, 내부 selector {pct(r['B']['internal']['final_accuracy'])}, validation에서 선택한 고정 정책 {sel['best_fixed']} {pct(r['B']['best_fixed']['final_accuracy'])}.\n- 내부 selector는 원래 오답 {r['original_errors']}개 중 {r['B']['internal']['successful_repairs']}개를 고쳤고, 원래 정답 {r['original_correct']}개 중 {r['B']['internal']['harmful_revisions']}개를 망가뜨렸습니다.\n- B 내부−외부 정확도 차이 {100*ci['B_internal_minus_external']['difference']:+.1f}%p, 95% CI {[round(100*v,1) for v in ci['B_internal_minus_external']['ci95']]}.\n\nLLM은 frozen Qwen2.5-1.5B-Instruct이며 작은 logistic classifier만 학습했습니다. A의 test 결과를 B 설정 선택에 사용하지 않았습니다. 네 action의 성공 label을 독립적으로 보존했고 Keep = 1 − A error를 전 사례에서 검증했습니다.\n\nPilot에서 token 경계 병합, 잘린 응답의 중간 숫자 채점, 결론 뒤 부수 숫자 추출 문제를 발견해 수정했습니다. 수정 후 pilot 원래 정답 {pilot['correct']}/40, oracle {pilot['oracle_successes']}/40입니다. Pilot 수치는 효과 검증 결과가 아닙니다.\n\n현재 GPU는 GTX 1080 Ti 11GB입니다. 새 추론 FP32와 이전 V100 FP16 원본의 차이, 작은 표본, 규칙 기반 숫자 추출, 제한적인 calculator 추출 범위를 한계로 기록했습니다. 기존 팀의 1,319 test 전체 실험과 직접 같은 설정은 아닙니다. 음성 결과와 넓은 불확실성도 그대로 보고합니다.\n\n상세 보고서는 REPORT.md, 재실행 명령은 ../../experiments/ab/README.md, 수치와 예측은 test_results.json 및 test_predictions.json을 확인하세요.\n'''
    ko+='\n정성 검토에서 공식 test 823번의 reference 오류(문제상 18점, reference 14점)를 확인했습니다. 주 결과는 공식 reference 채점을 유지했고 해당 1개를 제외한 민감도 분석을 별도로 기록했습니다. 이 분석에서도 hidden-state 이득이라는 결론은 나오지 않습니다.\n'
    (RUN/'REPORT_KO.md').write_text(ko)
    fig,ax=plt.subplots(1,2,figsize=(10,4));names=['D1','D2','D3','D4'];ax[0].bar(names,[r['A'][k]['AUROC'] for k in names],color=['#a1a1aa','#a1a1aa','#2563eb','#f97316']);ax[0].axhline(.5,color='gray',linestyle='--');ax[0].set(ylim=(0,1),ylabel='AUROC',title='A: original-error detection')
    names=['keep','best_fixed','external','internal'];ax[1].bar(names,[r['B'][k]['final_accuracy'] for k in names],color=['#a1a1aa','#64748b','#2563eb','#f97316']);ax[1].set(ylim=(0,1),ylabel='Final accuracy',title='B: action selection');fig.suptitle('Official GSM8K test subset, N=100');fig.tight_layout();fig.savefig(RUN/'results.png',dpi=180);plt.close(fig)
    names=['A_D4_minus_D3_AUROC','B_internal_minus_external','B_internal_minus_best_fixed'];fig,ax=plt.subplots(figsize=(8,3));point=np.array([ci[n]['difference'] for n in names]);bounds=np.array([ci[n]['ci95'] for n in names]);ax.errorbar(point,np.arange(3),xerr=np.stack([point-bounds[:,0],bounds[:,1]-point]),fmt='o',capsize=4);ax.axvline(0,color='gray',linestyle='--');ax.set_yticks(np.arange(3),['A: D4 − D3 AUROC','B: internal − external accuracy','B: internal − fixed accuracy']);ax.set_xlabel('Paired difference, 95% bootstrap CI');fig.tight_layout();fig.savefig(RUN/'paired_differences.png',dpi=180);plt.close(fig)
    print(RUN/'REPORT.md')
if __name__=='__main__':main()
